/* dedupe-last + identity→shared (स्वतः) */
function tidy(L) {
  const m = new Map();
  (L.words || []).forEach(p => m.set(String(p[0]).toLowerCase(), p));
  const keep = [], idshare = [];
  m.forEach((p, k) => {
    if (String(p[1]).toLowerCase() === k) idshare.push(k); else keep.push(p);
  });
  L.words = keep;
  L.shared = (L.shared || []).concat(idshare, PROPS);
}
